INSERT INTO public.legal_cases (slug, title, law_code, difficulty, story, question, options, answer_index, hint, explanation, articles, image_url, image_alt, published, reviewed_by, reviewed_on)
VALUES
  ($q$khutba-sadaq-istirdad$q$, $q$خطبة انتهت قبل العقد$q$, $q$mudawana-70-03$q$, $q$easy$q$, $q$تعرّف يوسف على سلمى في مدينة طنجة، وبعد أن اتفقت الأسرتان قدّم لها يوسف جزءاً من الصداق مسبقاً، تعبيراً عن جدية الخطبة.

بعد أسابيع تغيّرت ظروف يوسف، فعدل عن الخطبة قبل إبرام عقد الزواج، وطالب باسترداد ما سلّمه.$q$, $q$ما الحكم الذي ينطبق على طلب يوسف؟$q$, $q$["لا يحق له الاسترداد لأن ما قدّمه يُعد هبة لا ترد", "له استرداد ما سلّمه بعينه إن كان قائماً، وإلا فمثله أو قيمته يوم تسلّمه", "يسترد نصف المبلغ فقط في جميع الأحوال", "لا يسترد شيئاً إلا إذا وافقت سلمى على ذلك كتابةً"]$q$::jsonb, 1, $q$راجع المادة 9: ماذا يحق للخاطب استرداده عند العدول عن الخطبة؟$q$, $q$تنص المادة 9 على أن للخاطب أو لورثته استرداد ما سلّمه بعينه إن كان قائماً، وإلا فمثله أو قيمته يوم التسلّم. الحكم لا يتوقف على موافقة المخطوبة.$q$, $q$[{"law": "mudawana-70-03", "article": 9, "text": "إذا قدم الخاطب الصداق أو جزءا منه، وحدث عدول عن الخطبة أو مات أحد الطرفين أثناءها، فللخاطب أو لورثته استرداد ما سلم بعينه إن كان قائما، وإلا فمثله أو قيمته يوم تسلمه. إذا لم ترغب المخطوبة في أداء المبلغ الذي تحول إلى جهاز، يتحمل المتسبب في العدول ما قد ينتج عن ذلك من خسارة بين قيمة الجهاز والمبلغ المدفوع فيه. الباب الثاني: الزواج"}]$q$::jsonb, $q$/cases/khutba-sadaq-istirdad.jpg$q$, $q$خاتم وعلبة صغيرة على طاولة خشبية في جو عائلي هادئ$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$zawaj-thani-shart-zawja$q$, $q$شرط الزوجة في عقد الزواج$q$, $q$mudawana-70-03$q$, $q$medium$q$, $q$تزوج كريم من نادية، وأثبتا في عقد الزواج شرطاً تقدمت به نادية، وهو ألّا يتزوج كريم عليها.

بعد سنوات أراد كريم الزواج بأخرى، فاعترضت نادية، فاحتج كريم بأن التعدد مباح في الأصل.$q$, $q$هل يجوز لكريم الزواج بثانية؟$q$, $q$["نعم، لأن التعدد مباح في جميع الأحوال", "نعم، بشرط إخبار المحكمة فقط", "لا، لأن شرط الزوجة بعدم التزوج عليها يمنع التعدد", "لا، إلا إذا وافق القاضي بعد التقاضي"]$q$::jsonb, 2, $q$راجع المادة 40: في أي حالات يُمنع التعدد؟$q$, $q$تنص المادة 40 على أن التعدد يُمنع إذا خيف عدم العدل بين الزوجات، ويُمنع كذلك إذا وُجد شرط من الزوجة بعدم التزوج عليها.$q$, $q$[{"law": "mudawana-70-03", "article": 40, "text": "يمنع التعدد إذا خيف عدم العدل بين الزوجات، كما يمنع في حالة وجود شرط من الزوجة بعدم التزوج عليها."}]$q$::jsonb, $q$/cases/zawaj-thani-shart-zawja.jpg$q$, $q$عقد زواج مفتوح على طاولة مع قلم وأوراق رسمية$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$hadana-ajr-iddat-raji$q$, $q$أجرة الحضانة في العدة$q$, $q$mudawana-70-03$q$, $q$medium$q$, $q$طلّق عادل زوجته سلمى طلاقاً رجعياً، وبقي لهما طفل عمره ست سنوات، وأسندت المحكمة حضانته إلى الأم.

خلال عدتها طالبت سلمى الأب بأجرة الحضانة، فاعترض عادل بأن الطلاق لم يكتمل بعد.$q$, $q$هل تستحق سلمى أجرة الحضانة خلال عدتها من الطلاق الرجعي؟$q$, $q$["نعم، تستحقها كاملة منذ صدور الطلاق", "نعم، لكن نصفها فقط", "لا، لا تستحق أجرة الحضانة في عدة الطلاق الرجعي", "تستحقها فقط إذا رفض الأب الإنفاق على الطفل"]$q$::jsonb, 2, $q$راجع المادة 167: في أي حالات لا تستحق الأم أجرة الحضانة؟$q$, $q$تنص المادة 167 على أن أجرة الحضانة غير أجرة الرضاعة والنفقة، وأن الأم لا تستحق أجرة الحضانة في حال قيام العلاقة الزوجية، أو في عدة من طلاق رجعي.$q$, $q$[{"law": "mudawana-70-03", "article": 167, "text": "أجرة الحضانة ومصاريفها، على المكلف بنفقة المحضون وهي غير أجرة الرضاعة والنفقة. لا تستحق الأم أجرة الحضانة في حال قيام العلاقة الزوجية، أو في عدة من طلاق رجعي."}]$q$::jsonb, $q$/cases/hadana-ajr-iddat-raji.jpg$q$, $q$أم تحمل طفلاً صغيراً وتنظر إلى الأفق بجانب نافذة$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$wasiyya-li-warith$q$, $q$وصية لابن وارث$q$, $q$mudawana-70-03$q$, $q$hard$q$, $q$ترك الحاج محمد تركة، وكتب وصية يمنح فيها ابنه الأكبر، وهو من ورثته، نصف أمواله.

لم يوافق بقية الورثة على الوصية، فاحتج الابن بأنها كُتبت بإرادة والده وبإشهاد رسمي.$q$, $q$ما حكم هذه الوصية في حق الابن الوارث؟$q$, $q$["صحيحة كاملة لأن الوصية لا تتجاوز النصف", "صحيحة في حدود الثلث فقط، ولو لم يوافق الورثة", "غير نافذة في حقه إلا إذا أجازها بقية الورثة", "باطلة في جميع الأحوال، ولا يجوز الإشهاد بها"]$q$::jsonb, 2, $q$راجع المادة 277 لمعرفة ما تعطيه الوصية، ثم المادة 280 لحكم الوصية لوارث.$q$, $q$تنص المادة 277 على أن الوصية توجب حقاً في ثلث مال عاقدها، وتنص المادة 280 على أنه لا وصية لوارث إلا إذا أجازها بقية الورثة، مع بقاء الإشهاد بها جائزاً.$q$, $q$[{"law": "mudawana-70-03", "article": 277, "text": "الوصية عقد يوجب حقا في ثلث مال عاقده يلزم بموته."}, {"law": "mudawana-70-03", "article": 280, "text": "لا وصية لوارث إلا إذا أجازها بقية الورثة، غير أن ذلك لا يمنع من تلقي الإشهاد بها."}]$q$::jsonb, $q$/cases/wasiyya-li-warith.jpg$q$, $q$أوراق وثيقة قديمة مع ساعة جيب على طاولة خشبية$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$zawaj-qasir-muwafaqat-nai$q$, $q$زواج قاصر ورفض الولي$q$, $q$mudawana-70-03$q$, $q$medium$q$, $q$سارة في السادسة عشرة من عمرها، وتقدم لخطبتها شاب. رفض والدها، وهو نائبها الشرعي، الموافقة على الزواج.

عندها طلب الشاب تدخّل القضاء، وسألت الأسرة عمّا إذا كان الأب يملك حق الحسم النهائي.$q$, $q$ما الذي يقرره القانون في هذه الحالة؟$q$, $q$["يُعقد الزواج تلقائياً لأن الأب لا يملك حق الرفض", "يُمنع النظر في الطلب نهائياً ولو كانت الفتاة راضية", "يبت قاضي الأسرة المكلف بالزواج في الموضوع", "تبت الأم وحدها في الموافقة بعد إبرام العقد"]$q$::jsonb, 2, $q$راجع المادة 21: ماذا يحدث إذا امتنع النائب الشرعي عن الموافقة؟$q$, $q$زواج القاصر متوقف على موافقة نائبه الشرعي، فإذا امتنع النائب عن الموافقة بتّ قاضي الأسرة المكلف بالزواج في الموضوع.$q$, $q$[{"law": "mudawana-70-03", "article": 21, "text": "زواج القاصر متوقف على موافقة نائبه الشرعي. تتم موافقة النائب الشرعي بتوقيعه مع القاصر على طلب الإذن بالزواج وحضوره إبرام العقد. إذا امتنع النائب الشرعي للقاصر عن الموافقة بت قاضي الأسرة المكلف بالزواج في الموضوع."}]$q$::jsonb, $q$/cases/zawaj-qasir-muwafaqat-nai.jpg$q$, $q$قاضية تجلس أمام مكتب خشبي في قاعة محكمة بسيطة$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$iddat-bidayat-al-talaq$q$, $q$متى تبدأ العدة؟$q$, $q$mudawana-70-03$q$, $q$easy$q$, $q$وقع الطلاق بين ياسين ونور في الأول من مارس. ثم تساءلت نور عن بداية احتساب عدتها، وهل يحق لياسين مراجعتها إن كان الطلاق رجعياً.$q$, $q$من أي تاريخ تبتدئ العدة؟$q$, $q$["من تاريخ توقيع عقد الزواج الأول", "من تاريخ بلوغ الزوجة سن الأربعين", "من تاريخ الطلاق أو التطليق أو الفسخ أو الوفاة", "من تاريخ نشر الحكم في الجريدة الرسمية"]$q$::jsonb, 2, $q$راجع المادة 129 لمعرفة منذ متى تحسب العدة، ثم المادة 124 لحق المراجعة.$q$, $q$تنص المادة 129 على أن العدة تبتدئ من تاريخ الطلاق أو التطليق أو الفسخ أو الوفاة. وتنص المادة 124 على أن للزوج أن يراجع زوجته أثناء العدة إذا كان الطلاق رجعياً.$q$, $q$[{"law": "mudawana-70-03", "article": 129, "text": "تبتدئ العدة من تاريخ الطلاق أو التطليق أو الفسخ أو الوفاة."}, {"law": "mudawana-70-03", "article": 124, "text": "للزوج أن يراجع زوجته أثناء العدة. إذا رغب الزوج في إرجاع زوجته المطلقة طلاقا رجعيا أشهد على ذلك عدلين، ويقومان بإخبار القاضي فورا. يجب على القاضي قبل الخطاب على وثيقة الرجعة، استدعاء الزوجة لإخبارها بذلك، فإذا امتنعت ورفضت الرجوع، يمكنها اللجوء إلى مسطرة الشقاق المنصوص عليها في المادة 94 أعلاه."}]$q$::jsonb, $q$/cases/iddat-bidayat-al-talaq.jpg$q$, $q$تقويم مكتبي مفتوح على صفحة شهر مارس بجانب فنجان شاي$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$takhbir-ind-al-tawqif$q$, $q$إخبار الموقوف بأسباب التوقيف$q$, $q$constitution-2011$q$, $q$medium$q$, $q$أوقفت الشرطة شاباً في حي شعبي بالدار البيضاء، ولم تخبره بأسباب التوقيف إلا بعد ساعات، وبلغة لم يفهمها كاملاً.

يسأل الشاب عن الحد الأدنى الذي يضمنه الدستور في مثل هذه الحالة.$q$, $q$ما الذي يوجبه الفصل 23 في هذه الحالة؟$q$, $q$["لا شيء، فالإخبار بعد التوقيف إجراء شكلي", "إخبار الشخص بدواعي اعتقاله وبحقوقه على الفور وبكيفية يفهمها", "إخباره بالأسباب بعد إحالته على المحكمة فقط", "إخبار أسرته دون إخباره هو بأسباب التوقيف"]$q$::jsonb, 1, $q$راجع الفصل 23: متى يجب الإخبار، وبأي كيفية، وبأي المعلومات؟$q$, $q$ينص الفصل 23 على وجوب إخبار كل شخص تم اعتقاله، على الفور وبكيفية يفهمها، بدواعي اعتقاله وبحقوقه، ومن بينها حقه في التزام الصمت.$q$, $q$[{"law": "constitution-2011", "article": 23, "text": "لا يجوز إلقاء القبض على أي شخص أو اعتقاله أو متابعته أو إدانته، إلا في الحالات وطبقا للإجراءات التي ينص عليها القانون. الاعتقال التعسفي أو السري والاختفاء القسري، من أخطر الجرائم، وتعرض مقترفيها لأقسى العقوبات. يجب إخبار كل شخص تم اعتقاله، على الفور وبكيفية يفهمها، بدواعي اعتقاله وبحقوقه، ومن بينها حقه في التزام الصمت. ويحق له الاستفادة، في أقرب وقت ممكن، من مساعدة قانونية، ومن إمكانية الاتصال بأقربائه، طبقا للقانون. قرينة البراءة والحق في محاكمة عادلة مضمونان. يتمتع كل شخص معتقل بحقوق أساسية، وبظروف اعتقال إنسانية. ويمكنه أن يستفيد من برامج للتكوين وإعادة الإدماج. يُحظَر كل تحريض على العنصرية أو الكراهية أو العنف. يُعاقب القانون على جريمة الإبادة وغيرها من الجرائم ضد الإنسانية، وجرائم الحرب، وكافة الانتهاكات الجسيمة والممنهجة لحقوق الإنسان."}]$q$::jsonb, $q$/cases/takhbir-ind-al-tawqif.jpg$q$, $q$باب مكتب شرطة بسيط بجانب مقعد خشبي في ممر هادئ$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$hurmat-al-manzil$q$, $q$تفتيش منزل بلا إجراء$q$, $q$constitution-2011$q$, $q$easy$q$, $q$وصل عناصر من الشرطة إلى منزل أسرة في مدينة تطوان، وأرادوا تفتيشه بدعوى الاشتباه، دون إذن قضائي ولا وفق أي إجراء قانوني.$q$, $q$هل يجوز هذا التفتيش وفق الفصل 24؟$q$, $q$["نعم، لأن الاشتباه وحده يكفي لحرمة المنزل", "نعم، إذا كان التفتيش نهاراً", "لا، لا يجوز التفتيش إلا وفق الشروط والإجراءات التي ينص عليها القانون", "نعم، إذا وافقت الجارة على ذلك"]$q$::jsonb, 2, $q$راجع الفصل 24: ما الذي لا تُنتهك؟ ومتى يُسمح بالتفتيش؟$q$, $q$ينص الفصل 24 على أن حرمة المنزل لا تنتهك، ولا يمكن القيام بأي تفتيش إلا وفق الشروط والإجراءات التي ينص عليها القانون.$q$, $q$[{"law": "constitution-2011", "article": 24, "text": "لكل شخص الحق في حماية حياته الخاصة. لا تنتهك حرمة المنزل. ولا يمكن القيام بأي تفتيش إلا وفق الشروط والإجراءات التي ينص عليها القانون. لا تنتهك سرية الاتصالات الشخصية، كيفما كان شكلها. ولا يمكن الترخيص بالاطلاع على مضمونها أو نشرها، كلا أو بعضا، أو باستعمالها ضد أي كان، إلا بأمر قضائي، ووفق الشروط والكيفيات التي ينص عليها القانون. حرية التنقل عبر التراب الوطني والاستقرار فيه، والخروج منه، والعودة إليه، مضمونة للجميع وفق القانون."}]$q$::jsonb, $q$/cases/hurmat-al-manzil.jpg$q$, $q$باب منزل أزرق بنقوش تقليدية في زقاق تطواني$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
  ($q$tadhim-qarar-idari$q$, $q$الطعن في قرار بلدي$q$, $q$constitution-2011$q$, $q$easy$q$, $q$أصدرت البلدية قراراً بإغلاق محل تجاري يملكه سعيد دون أن تبين له الأسباب بوضوح. يريد سعيد أن يطعن في القرار.$q$, $q$أمام أي جهة يمكن لسعيد الطعن في القرار؟$q$, $q$["لا يمكن الطعن في القرارات الإدارية أبداً", "أمام الجهة الإدارية نفسها فقط", "أمام الهيئة القضائية الإدارية المختصة", "أمام الجمعية المهنية للتجار وحدها"]$q$::jsonb, 2, $q$راجع الفصل 118: ما نوع القرارات القابلة للطعن، وأمام أي هيئة؟$q$, $q$ينص الفصل 118 على أن كل قرار اتخذ في المجال الإداري، تنظيمياً كان أو فردياً، يمكن الطعن فيه أمام الهيئة القضائية الإدارية المختصة.$q$, $q$[{"law": "constitution-2011", "article": 118, "text": "حق التقاضي مضمون لكل شخص للدفاع عن حقوقه وعن مصالحه التي يحميها القانون. كل قرار اتخذ في المجال الإداري، سواء كان تنظيميا أو فرديا، يُمكن الطعن فيه أمام الهيئة القضائية الإدارية المختصة."}]$q$::jsonb, $q$/cases/tadhim-qarar-idari.jpg$q$, $q$واجهة محل تجاري صغير مغلق بشريط تحذير في شارع هادئ$q$, true, $q$مراجعة تحريرية داخلية$q$, DATE $q$2026-10-10$q$),
